// Builds the static geometry, colliders and baked lighting of one Yellow Rooms chunk.
// Surfaces are generated by the shared environment kit (src/world/env/): subdivided drywall with
// per-side finishes and skirting, cased doorways, corner beads, wall fixtures, the suspended acoustic
// ceiling with recessed troffers and damage, floors with analytic contact AO, maintenance pipe racks.
// Everything is merged per material (one draw call each) and lit per pixel by the grid light field.
import * as THREE from 'three';
import * as Mat from '../../../gfx/materials.js';
import { bakeGeometry, bakedMaterial, LightField } from '../../../gfx/bakedlight.js';
import { CELL, CHUNK, HEIGHT, W, getLayout, wallN, wallW, wallTransmission, cellInfo, floorDiv } from './layout.js';
import { buildModel } from '../../../entities/catalog.js';
import { hash01 } from '../../../core/rng.js';
import { EnvGeo, fr } from '../../env/builder.js';
import { GridBaker } from '../../env/gridbake.js';
import { ceilingCell, ceilingVoid } from '../../env/ceiling.js';
import { emitWallEdge, pillar } from '../../env/walls.js';
import { pipeRun } from '../../env/pipes.js';
import { fixtureMaterial } from '../../env/fixtures.js';
import { lightVolumes } from '../../env/haze.js';
import { floatingDebris } from '../../env/debris.js';

export const LIGHT_TONES = [
  new THREE.Color(1.0, 0.92, 0.72),  // 0 warm fluorescent
  new THREE.Color(0.92, 0.96, 1.0),  // 1 office cool
  new THREE.Color(1.0, 0.62, 0.32),  // 2 maintenance sodium
  new THREE.Color(1.0, 0.8, 0.55),   // 3 manila
  new THREE.Color(1.0, 0.12, 0.08),  // 4 red
  new THREE.Color(0.8, 0.95, 1.05),  // 5 pool
];
const TONE_INT = [1.0, 1.05, 0.75, 0.95, 0.9, 1.25];

// ---------------------------------------------------------------------------
// light helpers shared with the level (registration + baking queries)
export function cellLightSpec(cell) {
  if (!cell.light) return null;
  return {
    key: LightField.texel(cell.i, cell.j),
    x: (cell.i + 0.5) * CELL,
    y: HEIGHT - 0.04,
    z: (cell.j + 0.5) * CELL,
    radius: 9,
    color: LIGHT_TONES[cell.lightTone] || LIGHT_TONES[0],
    base: TONE_INT[cell.lightTone] ?? 1,
    mode: cell.lightMode,
    seed: cell.lightSeed,
  };
}

// 2D transmission between two points crossing cell edges (DDA over the cell grid)
export function makeOccluder(seed, variantFn) {
  return function occl(x0, z0, x1, z1) {
    let i = Math.floor(x0 / CELL), j = Math.floor(z0 / CELL);
    const ie = Math.floor(x1 / CELL), je = Math.floor(z1 / CELL);
    if (i === ie && j === je) return 1;
    const dx = x1 - x0, dz = z1 - z0;
    const stepI = dx > 0 ? 1 : -1, stepJ = dz > 0 ? 1 : -1;
    const tDx = dx !== 0 ? Math.abs(CELL / dx) : Infinity;
    const tDz = dz !== 0 ? Math.abs(CELL / dz) : Infinity;
    let tMx = dx !== 0 ? ((dx > 0 ? (i + 1) * CELL - x0 : x0 - i * CELL) / Math.abs(dx)) : Infinity;
    let tMz = dz !== 0 ? ((dz > 0 ? (j + 1) * CELL - z0 : z0 - j * CELL) / Math.abs(dz)) : Infinity;
    let tr = 1;
    for (let n = 0; n < 12 && (i !== ie || j !== je); n++) {
      if (tMx < tMz) {
        const wi = stepI > 0 ? i + 1 : i;
        tr *= wallTransmission(wallW(seed, wi, j, variantFn));
        i += stepI;
        tMx += tDx;
      } else {
        const wj = stepJ > 0 ? j + 1 : j;
        tr *= wallTransmission(wallN(seed, i, wj, variantFn));
        j += stepJ;
        tMz += tDz;
      }
      if (tr < 0.02) return 0;
    }
    return tr;
  };
}

export function makeAO(seed, variantFn) {
  const solid = (t) => t === W.FULL || t === W.DOOR || t === W.HALF_A || t === W.HALF_B || t === W.WINDOW;
  return function ao(x, y, z, nx, ny) {
    const i = Math.floor(x / CELL), j = Math.floor(z / CELL);
    const fx = x - i * CELL, fz = z - j * CELL;
    let d = 9;
    if (solid(wallN(seed, i, j, variantFn))) d = Math.min(d, fz);
    if (solid(wallN(seed, i, j + 1, variantFn))) d = Math.min(d, CELL - fz);
    if (solid(wallW(seed, i, j, variantFn))) d = Math.min(d, fx);
    if (solid(wallW(seed, i + 1, j, variantFn))) d = Math.min(d, CELL - fx);
    if (ny > 0.5) return 0.62 + 0.38 * Math.min(1, d / 0.9);
    if (ny < -0.5) return 0.75 + 0.25 * Math.min(1, d / 0.9);
    const v = Math.min(1, y / 0.5) * 0.25 + 0.75;
    const top = Math.min(1, (HEIGHT - y) / 0.4) * 0.15 + 0.85;
    return v * top;
  };
}

// surface style of a cell's walls: 'wall' (Level 0 wallpaper), 'manila', 'concrete' (painted block), 'pool'
function styleOfCell(c) {
  return c.roomStyle || (c.zone === 'maintenance' ? 'concrete' : c.zone === 'manila' ? 'manila' : 'wall');
}
function wetOfCell(c) {
  if (c.roomStyle === 'pool') return 0;
  if (c.zone === 'flooded') return c.water ? 1 : 0.65;
  return c.wet * 0.6;
}

// square cast floor drain: frame, slotted grate over a dark sump, a rust bloom around it
function floorDrain(G, x, z) {
  const m = G.metal, pl = G.plenum;
  const s = 0.13, y = 0.004;
  pl.ao = 0.15;
  pl.rect([x - s, 0.0015, z - s], [x + s, 0.0015, z - s], [x + s, 0.0015, z + s], [x - s, 0.0015, z + s], [0, 1, 0]);
  pl.ao = 1;
  m.ao = 0.9;
  const t = 0.018;
  m.box(x - s - t, 0, z - s - t, x + s + t, y, z - s, { ny: true });
  m.box(x - s - t, 0, z + s, x + s + t, y, z + s + t, { ny: true });
  m.box(x - s - t, 0, z - s, x - s, y, z + s, { ny: true });
  m.box(x + s, 0, z - s, x + s + t, y, z + s, { ny: true });
  for (let k = 1; k < 8; k++) {
    const zz = z - s + (k * 2 * s) / 8;
    m.box(x - s, 0.001, zz - 0.006, x + s, y - 0.0005, zz + 0.006, { ny: true });
  }
  m.ao = 1;
}

// zone carpets: the same synthesized pile, re-dyed (no extra texture memory)
const _carpets = {};
function carpetTint(k, hex) { return _carpets[k] || (_carpets[k] = Mat.make('carpet', { color: hex })); }

// maintenance block walls: the same synthesized set as the HQ, older paint (tinted)
let _cmuDirty = null;
function cmuDirty() { return _cmuDirty || (_cmuDirty = Mat.make('cmu', { color: 0xa69e88 })); }

// per-chunk build statistics (ms, accumulated) for profiling tools
export const buildStats = { geo: 0, bake: 0, mat: 0, decor: 0, phys: 0, water: 0, verts: 0, tris: 0, meshes: 0, n: 0 };

// ---------------------------------------------------------------------------
export function buildChunk(level, cx, cz) {
  let _t = performance.now();
  const lap = (k) => { const n = performance.now(); buildStats[k] += n - _t; _t = n; };
  const seed = level.seed;
  const variantFn = level.variantFn;
  const layout = getLayout(seed, cx, cz, variantFn(cx, cz));
  const N = CHUNK;
  const ox = cx * N * CELL, oz = cz * N * CELL;
  const group = new THREE.Group();
  group.name = `chunk:${cx},${cz}`;
  const rec = { colliders: [], group, layout, cx, cz, statics: [], waterCells: [] };
  const baker = new GridBaker(seed, variantFn, cx, cz);
  const info = (i, j) => cellInfo(seed, i, j, variantFn);

  const G = {
    wall: new EnvGeo({ wet: true, cap: 4096 }), manila: new EnvGeo({ wet: true }), concrete: new EnvGeo({ wet: true }), pool: new EnvGeo(),
    trim: new EnvGeo({ cap: 4096 }), rubber: new EnvGeo(), metal: new EnvGeo(), fixture: new EnvGeo({ color: true }),
    carpet: new EnvGeo({ edge: true, wet: true, cap: 2048 }), slab: new EnvGeo({ edge: true, wet: true }), tile: new EnvGeo({ edge: true }),
    carpetOffice: new EnvGeo({ edge: true, wet: true }), carpetManila: new EnvGeo({ edge: true, wet: true }), lensLouvre: new EnvGeo(),
    ceil: new EnvGeo({ edge: true, wet: true, cap: 4096 }), enamel: new EnvGeo({ cap: 2048 }), lens: new EnvGeo(), plenum: new EnvGeo(), debris: new EnvGeo(),
    pipe: new EnvGeo(), insul: new EnvGeo(), paper: new EnvGeo(),
  };

  // the spawn room's ceiling is torn open where the clones fall through
  let cut = null;
  for (const r of layout.specials) {
    if (r.kind !== 'spawn') continue;
    const cxm = (cx * N + r.rx + r.w / 2) * CELL, czm = (cz * N + r.rz + r.h / 2) * CELL;
    cut = { x0: cxm - 1.2, z0: czm - 1.2, x1: cxm + 1.2, z1: czm + 1.2 };
  }
  // --- floors & ceilings ---
  const wetAt = (x, z) => {
    // average wetness of the cells touching a floor vertex: soft transitions instead of cell squares
    const i0 = Math.floor((x - 0.01) / CELL), i1 = Math.floor((x + 0.01) / CELL);
    const j0 = Math.floor((z - 0.01) / CELL), j1 = Math.floor((z + 0.01) / CELL);
    let s = 0, n = 0;
    for (let j = j0; j <= j1; j++) for (let i = i0; i <= i1; i++) { s += wetOfCell(info(i, j)); n++; }
    return s / n;
  };
  for (const c of layout.cells) {
    const x0 = c.i * CELL, z0 = c.j * CELL;
    const g = c.floor === 'concrete' ? G.slab : c.floor === 'tile' ? G.tile
      : c.zone === 'office' || c.special?.kind === 'cubicle_farm' || c.special?.kind === 'office_room' ? G.carpetOffice
      : c.zone === 'manila' || c.roomStyle === 'manila' ? G.carpetManila : G.carpet;
    const [e0, e1] = baker.edgeInfo(c.i, c.j, false);
    g.edge0 = e0; g.edge1 = e1; g.ao = 1;
    if (g.Wt) g.wetFn = (x, y, z) => wetAt(x, z);
    g.grid([x0, 0, z0 + CELL], [CELL, 0, 0], [0, 0, -CELL], [0, 1, 0], fr(3), fr(3), (x, y, z) => [x, z]);
    ceilingCell(G, baker, c, seed, cut);
    if (c.water) rec.waterCells.push(c);
  }
  if (cut) ceilingVoid(G, cut, hash01(cx, cz, 5, seed));

  // --- walls on owned edges (N & W of each cell) ---
  const ctx = {
    G, seed, colliders: rec.colliders, fixtures: true,
    styleOf: (i, j) => styleOfCell(info(i, j)),
    wetOf: (i, j) => wetOfCell(info(i, j)),
  };
  for (const c of layout.cells) {
    const tN = layout.edgesN[c.lj * N + c.li];
    if (tN) emitWallEdge(ctx, c.i, c.j, 'x', tN);
    const tW = layout.edgesW[c.lj * N + c.li];
    if (tW) emitWallEdge(ctx, c.i, c.j, 'z', tW);
  }
  for (const p of layout.pillars) pillar(ctx, (cx * N + p.li) * CELL, (cz * N + p.lj) * CELL, p.size);

  // --- maintenance pipe racks (layout decor + extra runs along maintenance walls) ---
  const solidW = (i, j) => { const t = baker.edgeW(i, j); return t === W.FULL || t === W.LOW || t === W.WINDOW; };
  const solidN = (i, j) => { const t = baker.edgeN(i, j); return t === W.FULL || t === W.LOW || t === W.WINDOW; };
  for (const d of layout.decor) {
    if (d.kind !== 'pipes') continue;
    const i = cx * N + d.li, j = cz * N + d.lj;
    pipeRun(G, i, j, hash01(i, j, 81, seed), solidW(i, j), solidW(i + 1, j), 'x');
  }
  for (const c of layout.cells) {
    if (c.zone !== 'maintenance' || c.reserved) continue;
    const h = hash01(c.i, c.j, 82, seed);
    if (h < 0.1 && layout.edgesW[c.lj * N + c.li] === W.FULL) pipeRun(G, c.i, c.j, h * 10, solidN(c.i, c.j), solidN(c.i, c.j + 1), 'z');
    if (c.floor === 'concrete') {
      const hd = hash01(c.i, c.j, 83, seed);
      if (hd < 0.22) floorDrain(G, c.i * CELL + 0.6 + hd * 7.5, c.j * CELL + 0.6 + hash01(c.i, c.j, 84, seed) * 1.8);
    }
  }
  if (rec.waterCells.length) floatingDebris(G, rec.waterCells, seed);
  lap('geo');

  // --- materials & meshes ---
  const field = level.field;
  const add = (g, mat, grime, o = {}) => {
    if (g.isEmpty()) return null;
    const geo = g.build();
    const mix = o.mix || [1, 0.3];
    lap('geo');
    baker.bake(geo, { direct: mix[0], bounce: mix[1], quant: o.quant ?? 0.02, wallAO: !!o.wallAO });
    lap('bake');
    const m = bakedMaterial(mat, field, grime, { grid: 1, wet: !!g.Wt, ao: o.ao, mix, tiles: o.tiles, macro: o.macro, emissiveLights: o.emissive, spec: o.spec, lens: o.lens });
    const mesh = new THREE.Mesh(geo, m);
    mesh.receiveShadow = true;
    mesh.castShadow = !!o.cast;
    mesh.matrixAutoUpdate = false;
    group.add(mesh);
    buildStats.verts += geo.attributes.position.count;
    buildStats.tris += geo.index.count / 3;
    buildStats.meshes++;
    return mesh;
  };
  add(G.wall, Mat.get('wallpaper'), 2, { ao: 'wall', wallAO: true, cast: true, macro: 0.06 });
  add(G.manila, Mat.get('wallpaper_manila'), 2, { ao: 'wall', wallAO: true, cast: true, macro: 0.06 });
  add(G.concrete, cmuDirty(), 4, { ao: 'wall', wallAO: true, cast: true });
  add(G.pool, Mat.get('tile_pool'), 0, { ao: 'wall', wallAO: true, cast: true });
  add(G.trim, Mat.get('trim'), 0, { quant: 0.2 });
  add(G.rubber, Mat.get('rubber_base'), 0, { quant: 0.2 });
  add(G.metal, Mat.get('galvanized'), 0, { quant: 0.25 });
  add(G.fixture, fixtureMaterial(), 0, { quant: 0.3 });
  add(G.carpet, Mat.get('carpet'), 1, { ao: 'floor' });
  add(G.carpetOffice, carpetTint('office', 0xa4a49c), 1, { ao: 'floor' });
  add(G.carpetManila, carpetTint('manila', 0xc89c74), 1, { ao: 'floor' });
  add(G.slab, Mat.get('concrete_dark'), 4, { ao: 'floor' });
  add(G.tile, Mat.get('tile_pool'), 0, { ao: 'floor' });
  add(G.ceil, Mat.get('ceiling'), 3, { ao: 'ceil', tiles: true, mix: [0.22, 0.42] });
  add(G.enamel, Mat.get('enamel'), 0, { quant: 0.3, mix: [0.5, 0.6] });
  add(G.lens, Mat.get('lightpanel'), 0, { emissive: true, lens: true, quant: 0.6, mix: [0.2, 0.4] });
  add(G.lensLouvre, Mat.get('lightpanel'), 0, { emissive: true, lens: 'louvre', quant: 0.6, mix: [0.2, 0.4] });
  add(G.plenum, Mat.get('plenum'), 0, { quant: 0.3, mix: [0.3, 0.2] });
  add(G.debris, Mat.get('ceiling'), 0, { quant: 0.3 });
  add(G.pipe, Mat.get('pipe_paint'), 0, { quant: 0.3, cast: true });
  add(G.insul, Mat.get('insulation'), 0, { quant: 0.3, cast: true });
  add(G.paper, Mat.get('paper'), 0, { quant: 0.3 });
  // faint light shafts in the humid air under each fixture
  if (level.hazeOn !== false) {
    const haze = lightVolumes(layout, level);
    if (haze) group.add(haze);
  }
  lap('mat');

  // --- water ---
  if (rec.waterCells.length) {
    const wg = new EnvGeo({ cap: 512 });
    for (const c of rec.waterCells) {
      wg.grid([c.i * CELL, 0.09, (c.j + 1) * CELL], [CELL, 0, 0], [0, 0, -CELL], [0, 1, 0], fr(2), fr(2), (x, y, z) => [x, z]);
    }
    const geo = wg.build();
    bakeGeometry(geo, new THREE.Matrix4(), level.lightsNear, level.occluder, level.ao, { bounce: 0.5 });
    const mesh = new THREE.Mesh(geo, level.waterMaterial);
    mesh.renderOrder = 2;
    group.add(mesh);
    level.reflection.meshes.add(mesh);
    rec.waterMesh = mesh;
  }
  lap('water');

  // --- static decor (sunk / clipped furniture) ---
  for (const d of layout.decor) {
    const x = (cx * N + d.li) * CELL + CELL / 2, z = (cz * N + d.lj) * CELL + CELL / 2;
    if (d.kind === 'sunk') {
      const m = buildModel(d.type, { seed: d.li * 31 + d.lj });
      const o = m.object;
      o.position.set(x, (m.halfHeight ?? 0.4) - d.depth, z);
      o.rotation.set(d.tilt, d.rot, d.tilt * 0.5);
      level.prepStatic(o);
      group.add(o);
    } else if (d.kind === 'clip') {
      const m = buildModel(d.type, { seed: d.li * 17 + d.lj });
      const o = m.object;
      // half-way into the wall on the given side if a wall exists there
      if (d.side === 'N') { o.position.set(x + 0.2, m.halfHeight ?? 0.4, (cz * N + d.lj) * CELL + 0.05); o.rotation.y = 0.3; }
      else { o.position.set((cx * N + d.li) * CELL + 0.05, m.halfHeight ?? 0.4, z - 0.3); o.rotation.y = Math.PI / 2 + 0.25; }
      level.prepStatic(o);
      group.add(o);
    }
  }
  lap('decor');

  // --- colliders ---
  const phys = level.world.physics;
  const ud = { kind: 'static', surface: 'world' };
  const cols = [];
  cols.push(phys.addStaticBox(ox + N * CELL / 2, -0.25, oz + N * CELL / 2, N * CELL / 2, 0.25, N * CELL / 2, { kind: 'static', surface: 'floor' }));
  cols.push(phys.addStaticBox(ox + N * CELL / 2, HEIGHT + 0.25, oz + N * CELL / 2, N * CELL / 2, 0.25, N * CELL / 2, { kind: 'static', surface: 'ceiling' }));
  for (const b of rec.colliders) {
    cols.push(phys.addStaticBox((b.min.x + b.max.x) / 2, (b.min.y + b.max.y) / 2, (b.min.z + b.max.z) / 2,
      (b.max.x - b.min.x) / 2, (b.max.y - b.min.y) / 2, (b.max.z - b.min.z) / 2, ud));
  }
  rec.physicsColliders = cols;
  group.updateMatrixWorld(true);
  lap('phys');
  buildStats.n++;
  return rec;
}

export { floorDiv };
